mapper.select:
select 
from approval_rule

    and template_id = #{templateId}
    and rule_code = #{ruleCode}

        and rule_name like concat('%', #{ruleName}, '%')

    and scope_type = #{scopeType}
    and scope_id = #{scopeId}

        and business_subtype = #{businessSubtype}

    and rule_status = #{ruleStatus}

order by template_id, rule_id

select 
from approval_rule_version
where rule_id = #{ruleId} and version_no = #{versionNo}

mapper.insert:
insert into approval_rule (
    template_id, rule_code, rule_name, scope_type, scope_id,
    scope_name, business_subtype, rule_status, current_version_id,
    latest_version_no, lock_version, create_by, create_time, remark
) values (
    #{templateId}, #{ruleCode}, #{ruleName}, #{scopeType}, #{scopeId},
    #{scopeName}, #{businessSubtype}, #{ruleStatus},
    #{currentVersionId}, #{latestVersionNo}, 0, #{createBy},
    sysdate(), #{remark}
)

insert into approval_rule_version (
    rule_id, version_no, version_status, definition_snapshot,
    definition_checksum, published_by_user_id, published_by_name,
    published_time, lock_version, create_by, create_time, remark
) values (
    #{ruleId}, #{versionNo}, #{versionStatus}, #{definitionSnapshot},
    #{definitionChecksum}, #{publishedByUserId}, #{publishedByName},
    #{publishedTime}, 0, #{createBy}, sysdate(), #{remark}
)

mapper.update:
update approval_rule_version
set definition_snapshot = #{version.definitionSnapshot},
    definition_checksum = #{version.definitionChecksum},
    lock_version = lock_version + 1,
    update_by = #{version.updateBy},
    update_time = sysdate(),
    remark = #{version.remark}
where version_id = #{version.versionId}
  and version_status = 'DRAFT'
  and lock_version = #{expectedVersion}

mapper.insert:
insert into approval_rule_condition (
    version_id, condition_order, field_code, operator_code,
    value_type, value_text, create_by, create_time, remark
) values (
    #{versionId}, #{conditionOrder}, #{fieldCode}, #{operatorCode},
    #{valueType}, #{valueText}, #{createBy}, sysdate(), #{remark}
)
